import{d as g,C as e,o as h,c as d,j as i,a,E as t,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第12章","description":"《中庸》第 12 章——君子之道费而隐：夫妇可与知能行，其至则圣人有所不知不能；鸢飞鱼跃，上下昭著。","frontmatter":{"title":"中庸·第12章","description":"《中庸》第 12 章——君子之道费而隐：夫妇可与知能行，其至则圣人有所不知不能；鸢飞鱼跃，上下昭著。","category":"guide","aliases":["第12章","中庸第12章","费而隐"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-12.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-12.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-12.md"},b=g({...m,setup(p){const o=[{id:"feiyin",label:"费而隐 · 夫妇可与知能行",showLabel:!0,sentences:[["君子之道",{text:"费而隐",glossary:"feiyin"},"。",{text:"夫妇",glossary:"fufu"},"之愚，可以",{text:"与知",glossary:"yuzhi"},"焉；及其至也，虽圣人亦有所不知焉。夫妇之不肖，可以能行焉；及其至也，虽圣人亦有所不能焉。"]],note:"「君子之道费而隐」——君子之道，其用广大（费），其体精微（隐）。从近处说：寻常夫妇（愚者）也可以知道、可以实行；推到极处：即使圣人也有所不知、有所不能。此章总说君子之道「大而无外、细而无内」。"},{id:"daxiao",label:"语大莫能载 · 语小莫能破",showLabel:!0,sentences:[["天地之大也，人犹有所",{text:"憾",glossary:"han"},"。故君子语大，天下莫能",{text:"载",glossary:"zai"},"焉；语小，天下莫能",{text:"破",glossary:"po"},"焉。"]],note:"「天地之大也，人犹有所憾」——天地如此之大，人尚且有所不满足。故「君子语大，天下莫能载焉；语小，天下莫能破焉」：说它大，天下载不住；说它小，天下分不开。"},{id:"yuanfei",label:"鸢飞鱼跃 · 造端乎夫妇，察乎天地",showLabel:!0,sentences:[["《诗》云：“",{text:"鸢飞戾天",glossary:"yuanfei"},"，鱼跃于渊。”言其上下",{text:"察",glossary:"cha"},"也。君子之道，",{text:"造端",glossary:"zaoduan"},"乎夫妇；及其至也，察乎天地。"]],note:"引《诗》「鸢飞戾天，鱼跃于渊」——鸢飞上天、鱼跃深渊，说的正是道的「上下昭著」。故「君子之道，造端乎夫妇；及其至也，察乎天地」：从夫妇日用开端，推到极处则昭著于天地之间。"}],r=[{id:"feiyin",term:"费而隐",pinyin:"fèi ér yǐn",meaning:"朱注：「费，用之广也；隐，体之微也。」用途广大而本体精微——全章由此一对概念展开。"},{id:"fufu",term:"夫妇",pinyin:"fū fù",meaning:"匹夫匹妇，即普通人。朱注：「近自夫妇居室之间。」"},{id:"yuzhi",term:"与知",pinyin:"yù zhī",meaning:"参与、知道。与：读 yù（参与）。"},{id:"han",term:"憾",pinyin:"hàn",meaning:"遗憾、不满。朱注举「覆载生成之偏，及寒暑灾祥之不得其正者」。"},{id:"zai",term:"载",pinyin:"zài",meaning:"承载。语大而天下莫能载，极言其大。"},{id:"po",term:"破",pinyin:"pò",meaning:"剖分、说破。语小而天下莫能破，极言其小。"},{id:"yuanfei",term:"鸢飞戾天",pinyin:"yuān fēi lì tiān",meaning:"鸢（鸱类）飞至于天。戾：至。《诗·大雅·旱麓》句。"},{id:"cha",term:"察",pinyin:"chá",meaning:"昭著、显明。上下察，谓化育流行、上下昭著，莫非此理之用。"},{id:"zaoduan",term:"造端",pinyin:"zào duān",meaning:"开始、发端。"}];return(y,n)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第12章",tabindex:"-1"},[a("中庸·第12章 "),i("a",{class:"header-anchor",href:"#中庸·第12章","aria-label":'Permalink to "中庸·第12章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第十二章立起一对概念——"),i("strong",null,"费"),a("（用之广）与"),i("strong",null,"隐"),a("（体之微）：普通男女皆能知能行，推到极处连圣人也有不知不能；而「鸢飞鱼跃」，正是这道理上下昭著的样子。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),t(s,{colophon:"费而隐 · 鸢飞鱼跃 · 察乎天地",tone:"ink",sections:o,glossary:r,"default-mode":"slips","aria-label":"中庸·第12章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"费而隐",pinyin:["fèi","ér","yǐn"],meaning:"朱注：「费，用之广也；隐，体之微也。」一广一微，是全章的两端。"},{term:"夫妇",pinyin:["fū","fù"],meaning:"匹夫匹妇，普通人。朱注：「近自夫妇居室之间。」"},{term:"与知",pinyin:["yù","zhī"],meaning:"参与、知道。与：读 yù。"},{term:"憾",pinyin:["hàn"],meaning:"遗憾、不满。"},{term:"鸢飞戾天",pinyin:["yuān","fēi","lì","tiān"],meaning:"鸢（鸱类）飞至于天。戾：至。"},{term:"造端",pinyin:["zào","duān"],meaning:"开始、发端。「造端乎夫妇，及其至也，察乎天地」——两端都被点到。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>费而隐 · 夫妇可与知能行</strong>：君子的道，用途广大而本体精微。普通男女虽然愚昧，也可以知道一些；但到它的极处，即使圣人也有不知道的地方。普通男女虽不贤，也可以做到一些；但到它的极处，即使圣人也有做不到的地方。</p><p><strong>语大莫能载 · 语小莫能破</strong>：天地那么大，人尚且有所遗憾。所以君子说到大处，天下没有能承载它的；说到小处，天下没有能剖破它的。</p><p><strong>鸢飞鱼跃 · 造端乎夫妇，察乎天地</strong>：《诗经》说：「鸢飞戾天，鱼跃于渊。」说的正是道上下昭著。君子的道，从夫妇之间发端；到它的极处，昭著于天地之间。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十二章立起一对概念：<strong>费</strong>（用之广）与<strong>隐</strong>（体之微）。</p><p><strong>费</strong>：从夫妇居室之间，一直到圣人天地之所不能尽——其大无外，其小无内，普通人都能知、能行一些。 <strong>隐</strong>：而其所以然之理，隐而不可见。</p><p>最后以「鸢飞戾天，鱼跃于渊」作结：这不是写景，是说这道理<strong>上下昭著</strong>；而「造端乎夫妇，及其至也，察乎天地」，把范围的两端都点到了。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它同时防住两种傲慢</strong>：一是<strong>轻慢</strong>（「道嘛，匹夫匹妇都懂」），二是<strong>畏难</strong>（「圣人都不能尽，我算了吧」）。费与隐并存，两种态度都不成立。</li><li><strong>「有所不知、有所不能」是诚实</strong>：连圣人也如此。这一句给全篇留了余地——<strong>知道边界在哪，才是真知道</strong>。</li><li><strong>程子的评语值得记住</strong>：朱注引程子曰「此一节，子思吃紧为人处，活泼泼地」。鸢飞鱼跃四个字，把「道在日用而昭著」讲活了。</li><li><strong>它与第 13 章接续</strong>：本章说「费」（道之广），第 13 章紧接着说「道不远人」——由广而近，落到人身上。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>从近处入手</strong>：造端乎夫妇——最日常的关系，就是道的起点。</li><li><strong>承认极处不能尽</strong>：把「我不知道」说出来，是修为的一部分。</li><li><strong>练「活泼泼地」看</strong>：鸢飞鱼跃皆是道用；日常生活里也有这种昭著，只是常被略过。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>君子的道有两面：<strong>用得极广</strong>（费），<strong>本体极微</strong>（隐）。</p><p>广到什么程度？普通男女也能知道一些、做到一些。微到什么程度？推到极处，连圣人也有不知、不能的地方。所以往下说，它小到无处可破；往上说，它大到无处可载。</p><p>用《诗经》那两句作结最妙：<strong>鸢飞戾天，鱼跃于渊</strong>——上上下下，到处都是它。而它的起点，就是<strong>夫妇之间的日常</strong>；它的尽头，昭著于天地。</p><p>一句话：<strong>道大到圣人说不尽，小到从一间屋子开始。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「夫妇之愚，可以与知能行」——我愿不愿意承认，「道」就在最日常的地方？</li><li>「及其至也，虽圣人亦有所不知、有所不能」——说出「我不知道」，对我难不难？</li><li>「鸢飞戾天，鱼跃于渊」——我在日常生活里，见过哪些「道理昭著」的瞬间？</li><li>「造端乎夫妇」——我最该从哪一个具体关系开始？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-11">中庸·第11章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-13">中庸·第13章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',25))])}}});export{c as __pageData,b as default};
